
import VPopup from './VPopup.vue'

export default Vue.extend({
  name: 'VDropdown',
  components: {
    VPopup,
  },
  model: {
    prop: 'value',
    event: 'change',
  },
  props: {
    value: {
      required: true,
    },
    items: {
      type: Array,
      required: true,
    },
    keyMapper: {
      type: Function,
      default: (item: any) =>
        item !== null && typeof item === 'object' && 'name' in item ? item.name : item,
    },
    round: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      popupOpen: false,
    }
  },
  computed: {
    disabled() {
      return Boolean(this.$attrs.disabled)
    },
  },
  watch: {
    disabled(value: boolean) {
      if (value) {
        this.popupOpen = false
      }
    },
  },
  created() {
    if (this.value === null || this.value === undefined) {
      this.$emit('change', this.items[0] || '<No items>')
    }
  },
  methods: {
    selectItem(item: any) {
      let isChanged = false
      if (item && this.value && this.keyMapper) {
        isChanged = this.keyMapper(item) !== this.keyMapper(this.value)
      } else {
        isChanged = item !== this.value
      }

      if (isChanged) {
        this.$emit('change', item)
      }
      this.popupOpen = false
      this.$el.focus()
    },
    hit(event: Event) {
      if (this.disabled) {
        return
      }
      const popup = this.$refs.popup.$el as HTMLElement
      const target = event.target as HTMLElement
      if (popup !== target && !popup.contains(target)) {
        this.popupOpen = !this.popupOpen
      }
      // if (this.popupOpen) {
      //   if (popup.firstElementChild instanceof HTMLElement) {
      //     popup.firstElementChild.focus()
      //   }
      // }
    },
  },
})
