
import { DpiImage, VIcon } from '@/ui'

export default Vue.extend({
  components: {
    DpiImage,
    VIcon,
  },
  props: {
    href: {
      type: String,
      default: '',
    },
    upId: {
      type: [String, Number],
      default: '',
    },
    upFaceUrl: {
      type: String,
      default: '',
    },
    upName: {
      type: String,
      required: true,
    },
  },
  computed: {
    actualHref() {
      if (this.href) {
        return this.href
      }
      return `https://space.bilibili.com/${this.upId}`
    },
  },
})
